proc c_mutate_string(buffer: cstring, maxLen: cint) {.importc: "mutate_string", cdecl.}

proc getMutatedString*(prefix: string, maxExpectedLen: int): string =
  ## Pre-allocates a string buffer and allows C to mutate it
  result = newStringOfCap(maxExpectedLen)
  result.add(prefix)
  # Pad the rest with null bytes up to max expected length
  for i in 0 ..< (maxExpectedLen - prefix.len):
    result.add('\0')

  # Pass the underlying buffer to C
  c_mutate_string(cstring(result), cint(maxExpectedLen))

  # Recalculate Nim string length by finding the first null byte
  var actualLen = 0
  while actualLen < maxExpectedLen and result[actualLen] != '\0':
    inc(actualLen)

  result.setLen(actualLen)

