proc c_print_args(argc: cint, argv: ptr cstring) {.importc: "print_args", cdecl.}

proc passStringsToC*(args: seq[string]) =
  if args.len == 0:
    return

  # Create an array of cstring.
  # The original Nim strings in `args` stay alive for the duration of this proc.
  var cArgs = newSeq[cstring](args.len)
  for i in 0 ..< args.len:
    cArgs[i] = cstring(args[i])

  # Pass the pointer to the first element
  c_print_args(cint(args.len), addr cArgs[0])

