import std/os

proc c_blocking_work(seconds: cint): cint {.importc: "blocking_work", cdecl.}

var resChan: Channel[int]

proc workerThread(seconds: cint) {.thread.} =
  # This thread executes the blocking C FFI call
  let res = c_blocking_work(seconds)
  resChan.send(int(res))

proc startBlockingWork*(seconds: int) =
  resChan.open()
  var thr: Thread[cint]
  createThread(thr, workerThread, cint(seconds))

  echo "Main thread continuing while C function blocks..."
  sleep(500) # Do some main thread work
  echo "Main thread waiting for result..."

  let result = resChan.recv()
  echo "Result from C worker thread: ", result

  joinThread(thr)
  resChan.close()

