import std/posix

type
  Pipe* = object
    readFd*: cint
    writeFd*: cint

proc `=destroy`*(p: var Pipe) =
  if p.readFd >= 0:
    discard close(p.readFd)
    p.readFd = -1
  if p.writeFd >= 0:
    discard close(p.writeFd)
    p.writeFd = -1

proc `=copy`*(dest: var Pipe, source: Pipe) {.error: "Pipe cannot be copied, only moved".}

proc createPipe*(): Pipe =
  var fds: array[2, cint]
  if pipe(fds) != 0:
    raise newException(OSError, "Failed to create pipe")
  result.readFd = fds[0]
  result.writeFd = fds[1]

proc writeData*(p: Pipe, data: string) =
  if p.writeFd >= 0:
    discard write(p.writeFd, unsafeAddr data[0], data.len)

proc readData*(p: Pipe, maxLen: int): string =
  if p.readFd >= 0:
    result = newString(maxLen)
    let bytesRead = read(p.readFd, addr result[0], maxLen)
    if bytesRead >= 0:
      result.setLen(bytesRead)
    else:
      result.setLen(0)

when isMainModule:
  var myPipe = createPipe()
  myPipe.writeData("POSIX pipes in Nim")
  let msg = myPipe.readData(64)
  echo "Read from pipe: ", msg

import std/posix

iterator walkDirRaw*(path: string): string =
  ## Yields raw string names of files in a directory using POSIX APIs
  let dir = opendir(path.cstring)
  if dir != nil:
    try:
      while true:
        let entry = readdir(dir)
        if entry == nil:
          break
        # Convert char array to Nim string
        let nameStr = $cast[cstring](addr entry.d_name[0])
        if nameStr != "." and nameStr != "..":
          yield nameStr
    finally:
      discard closedir(dir)

