proc get_matrix(rows, cols: ptr cint): ptr ptr cfloat {.importc: "create_matrix", cdecl.}
proc free_matrix(mat: ptr ptr cfloat, rows: cint) {.importc: "free_matrix", cdecl.}

proc toNimMatrix*(): seq[seq[float]] =
  ## Imports a 2D array from C and converts it to a native Nim sequence matrix
  var rows, cols: cint
  let cMat = get_matrix(addr rows, addr cols)
  if cMat == nil:
    return @[]

  result = newSeq[seq[float]](rows)

  # Cast the outer pointer to an array of pointers
  let outerArr = cast[ptr UncheckedArray[ptr cfloat]](cMat)

  for i in 0 ..< int(rows):
    result[i] = newSeq[float](cols)
    # Cast the inner pointer to an array of floats
    let innerArr = cast[ptr UncheckedArray[cfloat]](outerArr[i])
    for j in 0 ..< int(cols):
      result[i][j] = float(innerArr[j])

  # Free the C-allocated structure after copying
  free_matrix(cMat, rows)

