      m[i] = malloc(3 * sizeof(float));
      for(int j=0; j<3; j++) m[i][j] = (float)(i + j);
    }
    return m;
  }
  void free_matrix(float** m, int r) {
    for(int i=0; i<r; i++) free(m[i]);
    free(m);
  }
  """.}

