proc get_env_vars(): ptr cstring {.importc: "get_envs", cdecl.}
proc free_env_vars(env: ptr cstring) {.importc: "free_envs", cdecl.}

proc fetchEnviron*(): seq[string] =
  ## Fetches a NULL-terminated array of strings from C
  result = @[]
  let cEnvs = get_env_vars()
  if cEnvs == nil:
    return

  # Cast to unchecked array of cstrings
  let arr = cast[ptr UncheckedArray[cstring]](cEnvs)

  var i = 0
  while arr[i] != nil:
    result.add($arr[i]) # The `$` operator copies cstring to a Nim string
    inc(i)

  # Clean up C memory
  free_env_vars(cEnvs)

