type
  CFlexStruct {.importc: "struct FlexMessage".} = object
    id: cint
    length: cint
    data: UncheckedArray[cfloat]

  FlexMessageObj = object
    ptrData: ptr CFlexStruct

proc `=destroy`*(m: var FlexMessageObj) =
  if m.ptrData != nil:
    dealloc(m.ptrData)
    m.ptrData = nil

proc newFlexMessage*(id: int, items: seq[float]): FlexMessageObj =
  # Calculate total bytes: size of struct (excluding flexible array) + size of array elements
  # In Nim, sizeof(CFlexStruct) might include 0 size for UncheckedArray, but it's safer to ensure we account for padding.
  let baseSize = sizeof(cint) * 2
  let arrayBytes = items.len * sizeof(cfloat)
  let totalBytes = baseSize + arrayBytes

  result.ptrData = cast[ptr CFlexStruct](alloc0(totalBytes))
  result.ptrData.id = cint(id)
  result.ptrData.length = cint(items.len)

  # Copy Nim seq data into the C flexible array
  for i in 0 ..< items.len:
    result.ptrData.data[i] = cfloat(items[i])

proc getItems*(m: FlexMessageObj): seq[float] =
  result = newSeq[float](m.ptrData.length)
  for i in 0 ..< int(m.ptrData.length):
    result[i] = float(m.ptrData.data[i])

