proc c_get_string_list(): ptr cstring {.importc: "get_str_list", cdecl.}

proc safeStringListCopy*(limit: int): seq[string] =
  ## Safely extracts up to `limit` strings from a C string array
  result = @[]
  let rawList = c_get_string_list()
  if rawList == nil:
    return

  let arr = cast[ptr UncheckedArray[cstring]](rawList)

  for i in 0 ..< limit:
    let cstr = arr[i]
    if cstr == nil:
      break # End of list reached early
    result.add($cstr)

