proc c_matrix_trace(mat: ptr cint, dim: cint): cint {.importc: "matrix_trace", cdecl.}

proc calculateTrace*(matrix: array[3, array[3, int]]): int =
  ## Passes a contiguous 2D Nim array to a C function expecting a flat pointer
  # We must use cint to match C exactly
  var cMatrix: array[3, array[3, cint]]
  for i in 0 ..< 3:
    for j in 0 ..< 3:
      cMatrix[i][j] = cint(matrix[i][j])

  # Pass the address of the first element
  result = int(c_matrix_trace(addr cMatrix[0][0], 3))

