  int matrix_trace(int* mat, int dim) {
    int sum = 0;
    for(int i = 0; i < dim; i++) {
      sum += mat[i * dim + i];
    }
    return sum;
  }
  """.}

  let myMat = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
  ]

  let trace = calculateTrace(myMat)
