proc doFragileWork(input: int): int =
  if input < 0:
    raise newException(ValueError, "Input cannot be negative")
  result = input * 2

proc nim_process_data(input: cint): cint {.exportc, cdecl, dynlib.} =
  ## Exported to C. Traps all Nim exceptions to prevent C crashes.
  try:
    let res = doFragileWork(int(input))
    result = cint(res)
  except ValueError:
    # Map specific error
    result = -1
  except CatchableError:
    # Map generic error
    result = -99

